  function render(){let names={overview:overview,train:trainer,routines:routinesPage,exercises:exercisePage,progress:progressPage,body:bodyPage,tools:toolsPage,settings:settingsPage};if(window.SetwiseGuide)window.SetwiseGuide.setDemoModel(db.preferences.demoModel);$('#exercise-count').textContent=all().length;$('#profile-units').textContent=db.preferences.unit==='lb'?'Imperial · lb':'Metric · kg';$('#active-pulse').classList.toggle('on',!!db.activeWorkout);mobileNav();$('#app-content').innerHTML=(names[view]||overview)();let rest=$('#default-rest');if(rest)rest.value=String(db.preferences.restSeconds);let settingRest=$('#settings-rest');if(settingRest)settingRest.value=String(db.preferences.restSeconds);let weeklyTarget=$('#settings-weekly-target');if(weeklyTarget)weeklyTarget.value=String(db.preferences.weeklyTarget||4);syncInstallUI();}
